function alternateDigitSum(n) {
  const digits = String(n).split('');
  let total = 0;
  for (let i = 0; i < digits.length; i++) {
    total += i % 2 === 0 ? Number(digits[i]) : -Number(digits[i]);
  }
  return total;
}

