function generate(rand, size) {
  if (rand() < 0.1) return [1000000000];
  const length = size === 'large' ? 7 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 9);
  let n = 1 + Math.floor(rand() * 9);
  for (let i = 1; i < length; i++) n = n * 10 + Math.floor(rand() * 10);
  return [n];
}
